WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS new_group_flag FROM sessions), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), gaps_2 AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag_2 FROM islands), sessions_sessions AS (SELECT *, SUM(new_group_flag_2) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps_2), not_flagged AS (SELECT s.* FROM sessions_sessions s WHERE EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time < s.started_at)), kept AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.session_id IN (10, 36, 37))) SELECT browser, session_no, SUM(burst_id) AS total_burst_id, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(*) FILTER (WHERE browser = 'Edge') AS edge_rows, MIN(started_at) AS started_at, COUNT(*) AS row_count FROM kept GROUP BY browser, session_no ORDER BY total_burst_id;
